#include "search.h"
using namespace v2;
int main(int argc,char**argv){try{init();Learner model;model.load("training/v7/base.ntd");v9::Net zero;zero.context=zero.policy=true;zero.initialize(42);v9::Net policy=zero;if(argc==2)policy.load(argv[1]);for(int j=0;j<v9::H;j++)if(policy.w[v9::V+j]!=0)throw std::runtime_error("value head changed");if(policy.w[v9::O]!=0)throw std::runtime_error("value bias changed");MCTS base(model);RootPolicySearch blank(model,zero),student(model,policy);base.budget=blank.budget=student.budget=100;base.maxSimulations=blank.maxSimulations=student.maxSimulations=256;RNG rng{11610001};Game g;g.reset(rng);Counts c=opening(g);for(int i=0;i<80;i++){uint32_t seed=1000+i;auto a=base.choose(g.b,g.next,c,seed);auto b=blank.choose(g.b,g.next,c,seed);if(a.direction!=b.direction)throw std::runtime_error("zero policy parity");for(int d=0;d<4;d++)if(base.nodes[0]->edges[d].visits!=blank.nodes[0]->edges[d].visits)throw std::runtime_error("visits parity");student.choose(g.b,g.next,c,seed);for(size_t j=0;j<student.nodes.size();j++){auto&n=*student.nodes[j];double sum=0;for(auto&e:n.edges)if(e.move.size){if(e.initial!=e.move.reward+model.value(e.move.b,stage(e.move.b)))throw std::runtime_error("value changed");sum+=std::exp(std::max(-20.,(e.initial-n.leaf)/student.temperature));}if(j)for(auto&e:n.edges)if(e.move.size&&std::abs(e.prior-std::exp(std::max(-20.,(e.initial-n.leaf)/student.temperature))/sum)>1e-12)throw std::runtime_error("internal prior changed");}g.advance(move(g.b,a.direction),rng);c=observe(c,g.next);if(g.over||high(g.b)>=12){g.reset(rng);c=opening(g);}}std::cout<<"80 zero-policy root-action/visits parity cases; learned value head zero; all visited values and internal priors unchanged\n";}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
